def _master_format_txt_segment(segment):
    """把单个 TXT bytes 段渲染为带双引号的主文件字符串。

    双引号与反斜杠写 \\"、\\\\，其余可打印字节（0x20..0x7E）原样写，
    非打印字节写三位十进制 \\DDD；空段渲染为 ""。
    """
    out = ['"']
    for value in segment:
        if value == 0x22:
            out.append('\\"')
        elif value == 0x5C:
            out.append("\\\\")
        elif 0x20 <= value <= 0x7E:
            out.append(chr(value))
        else:
            out.append("\\%03d" % value)
    out.append('"')
    return "".join(out)


